const key='kwast-pilot-3', date=d=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'short'}).format(new Date(d+'T12:00:00')), price=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n);
const day=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
