function seed(){return {me:'c0',companies:names.map((name,i)=>({id:'c'+i,name,city:cities[i],team:[4,6,3,7][i],cv:['Отделка офисных помещений','Реставрация фасадов','Интерьеры квартир','Коммерческая отделка'][i],experience:['Haven Bouw','Atelier Oost','Wonen Noord','Bureau West'][i],proof:'demo',gallery:[],demo:true})),jobs:['Покраска офиса у канала','Отделка жилого комплекса','Обновление фасада','Покраска шоурума','Реставрация окон','Отделка мастерской'].map((title,i)=>({id:'j'+i,title,city:cities[i],owner:'c'+[1,2,0,3,1,2][i],status:['open','open','booked','open','open','done'][i],price:[3400,5850,4200,2700,3200,1900][i],team:[3,5,4,2,3,2][i],start:day([3,5,2,7,10,-8][i]),end:day([8,14,12,10,16,-2][i]),area:[180,420,240,145,95,110][i],desc:['Подготовка стен и покраска офисных помещений в два слоя. Материалы на объекте.','Финишная отделка стен и потолков в новых квартирах.','Подготовка и покраска уличного фасада.','Стены и деревянные панели торгового зала.','Подготовка рам и нанесение защитного покрытия.','Внутренняя отделка стен мастерской.'][i],offers:i===2||i===5?[{by:'c3',price:i===2?4200:1900,note:'Готовы выполнить заказ.'}]:[],accepted:i===2||i===5?'c3':null}))}}

// ---- Режимы: «demo» — локальные данные на устройстве (как в прежнем пилоте), «server» — рабочий аккаунт и общая база.
const connKey='kwast-connection', cacheKey='kwast-server-cache';
const readJSON=k=>{try{return JSON.parse(localStorage.getItem(k))}catch{return null}}, writeJSON=(k,v)=>{try{v==null?localStorage.removeItem(k):localStorage.setItem(k,JSON.stringify(v))}catch{}};
let conn=readJSON(connKey)||{}, remote=conn.mode==='server', offline=false, pollTimer;
const defaultServer=()=>{const c=String(window.KWAST_SERVER||'').trim();if(c)return c;if(/^https?:$/.test(location.protocol)&&location.hostname!=='appassets.androidplatform.net')return location.origin;return ''};
const normServer=s=>{s=String(s||'').trim().replace(/\/+$/,'');if(s&&!/^https?:\/\//i.test(s))s='http://'+s;return s};
const host=s=>{try{return new URL(s).host}catch{return s}};
function setConn(next){conn=next;remote=conn.mode==='server';writeJSON(connKey,conn)}
function loadDemo(){try{st=JSON.parse(localStorage.getItem(key));if(!st?.companies||!st.jobs||!st.companies.some(c=>c.id===st.me))st=seed()}catch{st=seed()}}
let st=null;

let page='jobs',filter='all',mode='map',toastTimer,openJob=null;const company=id=>st.companies.find(c=>c.id===id)||{id,name:'Компания',city:'',team:0}, job=id=>st.jobs.find(j=>j.id===id), me=()=>company(st.me), initial=n=>n.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase(), avatar=c=>c.portrait?'<img class="avatar" alt="" src="'+esc(c.portrait)+'">':'<span class="avatar">'+esc(initial(c.name))+'</span>';
function toast(msg){const t=$('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',3800)}
function save(mut){const before=JSON.stringify(st);try{mut();localStorage.setItem(key,JSON.stringify(st));return true}catch{st=JSON.parse(before);toast('Сохранение недоступно. Проверьте свободное место на устройстве.');return false}}

// ---- Связь с сервером
async function api(method,path,body){
 let res;
 try{res=await fetch(conn.server+path,{method,headers:{'Content-Type':'application/json',...(conn.token?{Authorization:'Bearer '+conn.token}:{})},body:body?JSON.stringify(body):undefined})}
 catch{throw Object.assign(Error('Нет связи с сервером '+host(conn.server)+'. Проверьте интернет и адрес сервера.'),{status:0})}
 let data={};try{data=await res.json()}catch{}
 if(!res.ok){const e=Object.assign(Error(data.error||'Ошибка сервера ('+res.status+').'),{status:res.status});if(res.status===401&&conn.token){signOut('Сессия завершена. Войдите снова.')}throw e}
 if(data.state)applyState(data.state);
 return data
}
function applyState(s){offline=false;st={me:s.me,companies:s.companies,jobs:s.jobs,bookings:s.bookings||[],feePercent:s.feePercent};writeJSON(cacheKey,{server:conn.server,me:s.me,state:s})}
async function refresh(){const before=JSON.stringify(st);await api('GET','/api/state');return JSON.stringify(st)!==before}
// Сервер — источник истины: при отказе (409) подтягиваем свежие данные и показываем причину.
async function remoteAct(fn,jobId){try{await fn()}catch(e){toast(e.message);if(e.status===401)return;if(e.status!==0)await refresh().catch(()=>{});if(st){render();if(jobId)showJob(jobId)}}}
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(sync,10000)}
async function sync(){if(!remote||!conn.token||document.hidden||!st)return;if(dlg.open&&$('#modal form'))return;try{const changed=await refresh();if(changed||offline){render();if(dlg.open&&openJob){const y=dlg.scrollTop;showJob(openJob);dlg.scrollTop=y}}}catch(e){if(e.status===0&&!offline){offline=true;render()}}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync()});
function signOut(msg){const token=conn.token;if(token&&!msg)fetch(conn.server+'/api/logout',{method:'POST',headers:{Authorization:'Bearer '+token}}).catch(()=>{});clearInterval(pollTimer);writeJSON(cacheKey,null);setConn({mode:'server',server:conn.server});st=null;if(dlg.open)dlg.close();gate('login');if(msg)toast(msg)}
function enterDemo(){clearInterval(pollTimer);setConn({mode:'demo',server:conn.server});loadDemo();page='jobs';if(dlg.open)dlg.close();render();toast('Демо-режим: данные только на этом устройстве')}

const act=(name,id='',label='',cls='')=>'<button class="'+cls+'" data-action="'+name+'" data-id="'+esc(id)+'">'+label+'</button>';
function nav(){return Object.entries(pages).map(([k,v])=>'<button class="navbtn '+(page===k?'active':'')+'" data-page="'+k+'">'+icon(k)+'<span>'+v+'</span></button>').join('')}
function card(j){return '<button class="job" data-action="job" data-id="'+esc(j.id)+'"><div class="cardTop"><span class="pill '+j.status+'">'+labels[j.status]+'</span><span class="price">'+price(j.price)+'</span></div><h3>'+esc(j.title)+'</h3><div class="meta">'+icon('pin')+' '+esc(city(j.city))+' <span class="sep">·</span> '+date(j.start)+' <span class="sep">·</span> '+j.team+' чел.</div></button>'}
function cards(js){return js.length?js.map(card).join(''):'<p class="empty">Пока нет объектов.</p>'}
const bookingLabels={booked:'Бронь активна',cancelled:'Бронь отменена',done:'Работы завершены'};
function bookingCard(b){const other=b.owner===st.me?'Исполнитель: '+company(b.crew).name:'Заказчик: '+company(b.owner).name;return '<button class="job" data-action="job" data-id="'+esc(b.job)+'"><div class="cardTop"><span class="pill '+(b.status==='booked'?'booked':b.status==='done'?'done':'cancelled')+'">'+bookingLabels[b.status]+'</span><span class="price">'+price(b.price)+'</span></div><h3>'+esc(b.title)+'</h3><div class="meta">'+icon('calendar')+' '+date(b.start)+' – '+date(b.end)+' <span class="sep">·</span> '+b.team+' чел.</div><div class="meta">'+esc(other)+'</div></button>'}
function footer(){return remote?'<i class="'+(offline?'off':'')+'"></i> '+(offline?'Нет связи · ':'Сервер · ')+esc(host(conn.server)):'<i></i> Демо на этом устройстве'}
function render(){if(!st){gate();return}document.body.classList.remove('gate');document.body.classList.toggle('offline',offline);const n=nav();$('nav').innerHTML=n;$('.mobileNav').innerHTML=n;$('.sideFoot').innerHTML=footer();$('#account').innerHTML=avatar(me())+'<span class="accountName">'+esc(me().name)+(remote?'':' · демо')+'</span>'+icon('down');$('#crumb').textContent=pages[page];$('#heading').textContent=intro[page][0];$('#sub').textContent=offline?'Нет связи с сервером. Показаны последние сохранённые данные.':intro[page][1];$('.publish').innerHTML=icon('plus')+'Разместить объект';const v=$('#view');if(page==='orgs'){v.innerHTML='<div class="directory">'+st.companies.map(c=>'<button class="panel org" data-action="profile" data-id="'+c.id+'">'+avatar(c)+'<h3>'+esc(c.name)+'</h3><div class="meta">'+icon('pin')+esc(city(c.city))+' · '+c.team+' чел.</div><p class="muted">'+esc(c.cv)+'</p></button>').join('')+'</div>';return}
if(page==='deals'){const own=st.jobs.filter(j=>j.owner===st.me),mine=st.jobs.filter(j=>j.offers.some(o=>o.by===st.me));v.innerHTML=(remote?'<h2>Бронирования</h2><div class="directory mt">'+(st.bookings.length?st.bookings.map(bookingCard).join(''):'<p class="empty">Бронирований пока нет.</p>')+'</div><h2 class="mt">Мои объекты</h2>':'<h2>Мои объекты</h2>')+'<div class="directory mt">'+cards(own)+'</div><h2 class="mt">Мои отклики</h2><div class="directory mt">'+cards(mine)+'</div>';return}
const js=st.jobs.filter(j=>filter==='all'||j.status===filter);
v.innerHTML='<div class="stats">'+[[st.jobs.filter(j=>j.status==='open').length,'Открытые объекты','jobs'],[st.jobs.filter(j=>j.status==='booked').length,'Забронированы','calendar'],[st.companies.length,'Компании','users']].map(([n,l,i],k)=>'<div class="stat"><span class="statIcon a'+k+'">'+icon(i)+'</span><div><strong>'+n+'</strong><small>'+l+'</small></div></div>').join('')+'</div><div class="mobileTabs">'+act('mode','map','Карта','chip '+(mode==='map'?'active':''))+act('mode','list','Список','chip '+(mode==='list'?'active':''))+'</div><div class="board mode-'+mode+'"><section class="panel mapPanel"><div class="panelHead"><h2>Карта объектов</h2><span class="caption">Нидерланды</span></div><div id="map" class="mapbox"></div><div class="legend"><span><i class="dot"></i>Открыт</span><span><i class="dot purple"></i>Забронирован</span><span><i class="dot grey"></i>Завершён</span></div></section><section class="panel listPanel"><div class="panelHead"><h2>Объекты</h2><span class="caption">'+js.length+' из '+st.jobs.length+'</span></div><div class="filter">'+[['all','Все'],['open','Открытые'],['booked','Бронь'],['done','Завершены']].map(([k,v])=>act('filter',k,v,'chip '+(k===filter?'active':''))).join('')+'</div><div class="cards">'+cards(js)+'</div></section></div>';if(window.KwastMap)KwastMap.render($('#map'),js,id=>showJob(String(id)),null)}
const dlg=$('#dialog');function modal(tag,html,jobId=null){openJob=jobId;$('#modalTag').textContent=tag;$('#modal').innerHTML=html;if(!dlg.open)dlg.showModal();dlg.scrollTop=0}
$('#close').onclick=()=>dlg.close();dlg.addEventListener('close',()=>openJob=null);dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});
const feeRate=()=>(st?.feePercent??8);
function settle(by,amt){const fee=Math.round(amt*feeRate())/100;return '<div class="note">Стоимость '+price(amt)+' · Комиссия '+feeRate()+'%: '+price(fee)+' · Исполнителю: '+price(amt-fee)+'. Тестовый расчёт комиссии — деньги не списываются.</div>'}
// Предварительная проверка на устройстве. В рабочем режиме окончательно решает сервер.
function available(j,by,limit=company(by)?.team){
 const crew=company(by);if(!crew||j.team>limit)return false;
 const shifts=new Map();
 for(const other of st.jobs){
  if(other.id===j.id||other.status!=='booked'||other.accepted!==by||other.start>j.end||other.end<j.start)continue;
  const first=Math.max(Date.parse(j.start),Date.parse(other.start)),after=Math.min(Date.parse(j.end),Date.parse(other.end))+86400000;
  shifts.set(first,(shifts.get(first)||0)+other.team);shifts.set(after,(shifts.get(after)||0)-other.team);
 }
 let used=j.team;
 for(const t of [...shifts.keys()].sort((a,b)=>a-b)){used+=shifts.get(t);if(used>limit)return false}
 return true
}
function cancelBooking(j,commit){
 if(!j||j.status!=='booked'||(j.owner!==st.me&&j.accepted!==st.me))return;
 if(!commit){modal('БРОНИРОВАНИЕ','<h2>Отменить бронь?</h2><p>Объект снова откроется для предложений. Бригада освободится на эти даты.'+(remote?' Вторая сторона увидит отмену.':'')+'</p><div class="actions">'+act('doCancel',j.id,'Отменить бронь')+act('job',j.id,'Сохранить бронь','primary')+'</div>');return}
 if(remote)return remoteAct(async()=>{await api('POST','/api/jobs/'+encodeURIComponent(j.id)+'/cancel');render();showJob(j.id);toast('Бронь отменена')},j.id);
 if(save(()=>{j.offers=j.offers.filter(o=>o.by!==j.accepted);j.accepted=null;j.status='open'})){render();showJob(j.id);toast('Бронь отменена')}
}
const stamp=t=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(t));
function history(j){const list=(st.bookings||[]).filter(b=>b.job===j.id);if(!list.length)return '';return '<h3>История брони</h3>'+list.map(b=>'<div class="info"><span class="pill '+(b.status==='booked'?'booked':b.status==='done'?'done':'cancelled')+'">'+bookingLabels[b.status]+'</span> '+esc(company(b.crew).name)+' · '+date(b.start)+' – '+date(b.end)+' · <b>'+price(b.price)+'</b><br><small class="muted">Подтверждена '+stamp(b.createdAt)+(b.closedAt?' · '+(b.status==='cancelled'?'отменил(а) ':'закрыл(а) ')+esc(company(b.closedBy).name)+' '+stamp(b.closedAt):'')+'</small></div>').join('')}
function showJob(id){let j=job(id);if(!j)return;const own=j.owner===st.me,accepted=j.offers.find(o=>o.by===j.accepted),my=j.offers.find(o=>o.by===st.me);let actions='';if(own&&j.status==='open'){actions='<h3>Предложения бригад</h3>'+(j.offers.map(o=>'<div class="offer"><div class="flex">'+act('profile',o.by,esc(company(o.by).name),'textbtn')+'<b>'+price(o.price)+'</b></div><p>'+esc(o.note)+'</p>'+settle(o.by,o.price)+act('book',id+'|'+o.by,'Забронировать бригаду','primary')+'</div>').join('')||'<p class="muted">Откликов пока нет.</p>')}
if(!own&&j.status==='open')actions=my?'<div class="info">Ваше предложение: <b>'+price(my.price)+'</b> · ждёт решения заказчика</div>':act('offer',id,'Предложить бригаду','primary');
if(accepted)actions='<h3>Исполнитель</h3>'+act('profile',accepted.by,esc(company(accepted.by).name),'textbtn')+((own||accepted.by===st.me)?'<div class="info">'+date(j.start)+' – '+date(j.end)+' · '+j.team+' чел. · <b>'+price(accepted.price)+'</b></div>'+settle(accepted.by,accepted.price):'')+(own&&j.status==='booked'?'<div class="actions">'+act('finish',id,'Подтвердить завершение','primary')+'</div>':'');
if(j.status==='booked'&&(own||j.accepted===st.me))actions+='<div class="actions">'+act('cancelBooking',id,'Отменить бронь')+'</div>';
if(remote)actions+=history(j);
modal('КАРТОЧКА ОБЪЕКТА','<span class="pill '+j.status+'">'+labels[j.status]+'</span><h2>'+esc(j.title)+'</h2><div class="meta">'+icon('pin')+esc(city(j.city))+' · '+date(j.start)+' – '+date(j.end)+'</div><div class="info"><b>'+price(j.price)+'</b> · '+j.team+' чел. · '+j.area+' м²</div><p>'+esc(j.desc)+'</p><h3>Заказчик</h3>'+act('profile',j.owner,esc(company(j.owner).name),'textbtn')+'<div class="mt">'+actions+'</div>',id)}
function profile(id){const c=company(id);if(!c)return;modal('ПРОФИЛЬ КОМПАНИИ','<div class="split">'+avatar(c)+'<h2>'+esc(c.name)+'</h2></div><p class="meta">'+icon('pin')+esc(city(c.city))+' · '+c.team+' чел.'+(c.demo?' · Демо-компания':'')+'</p><h3>О команде</h3><p>'+esc(c.cv||'Описание пока не добавлено.')+'</p><h3>Опыт работы</h3><p>'+esc(c.experience||'Компании пока не указаны.')+'</p>'+(c.proof==='demo'?'<span class="label">✓ Подтверждено · пример</span>':c.proof==='pending'?'<span class="pill booked">Ожидает проверки · тестовый документ</span>':'')+'<h3>Портфолио</h3>'+(c.gallery?.length?'<div class="gallery">'+c.gallery.map(s=>'<img src="'+esc(s)+'" alt="Работа компании">').join('')+'</div>':'<p class="muted">Фотографии пока не добавлены.</p>')+(id===st.me?'<div class="actions">'+act('editProfile',id,'Изменить профиль')+'</div>':''))}
function accounts(){
 if(remote){const c=me();modal('РАБОЧИЙ АККАУНТ','<div class="split">'+avatar(c)+'<h2>'+esc(c.name)+'</h2></div><p class="note">Вы вошли как '+esc(c.email||'')+'. Объекты, отклики и брони хранятся на сервере '+esc(host(conn.server))+' и видны с любого устройства этой компании.</p><div class="actions">'+act('profile',st.me,'Мой профиль','primary')+act('refresh','','Обновить данные')+act('signOut','','Выйти')+'</div><div class="actions">'+act('demo','','Открыть демо без регистрации','textbtn')+'</div>');return}
 modal('ДЕМО-КАБИНЕТ','<h2>Сменить компанию</h2><p class="note">Переключайтесь между участниками, чтобы проверить обе стороны сделки. Данные сохраняются только на этом устройстве.</p>'+st.companies.map(c=>'<button class="switch '+(st.me===c.id?'active':'')+'" data-action="switch" data-id="'+c.id+'">'+avatar(c)+'<span>'+esc(c.name)+'<br><small>'+(st.me===c.id?'Текущая компания':esc(city(c.city)))+'</small></span></button>').join('')+'<div class="actions">'+act('newProfile','','Зарегистрировать демо-компанию')+act('profile',st.me,'Мой профиль')+'</div><div class="actions">'+act('login','','Войти в рабочий аккаунт','primary')+'</div>')}
$('#account').onclick=accounts;
const field=(l,input)=>'<label>'+l+input+'</label>', inp=(n,v='',extra='')=>'<input name="'+n+'" value="'+esc(v)+'" '+extra+'>', opts=(v='')=>'<select name="city">'+cities.map((c,i)=>'<option value="'+c+'" '+(c===v?'selected':'')+'>'+cityNames[i]+'</option>').join('')+'</select>';
function form(tag,title,body,submit){modal(tag,'<h2>'+title+'</h2><form class="fields" id="entry">'+body+'<div class="formerr" role="alert"></div><button type="submit" class="primary">'+submit+'</button></form>')}
function onSubmit(fn){$('#entry').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,button=f.querySelector('[type=submit]');button.disabled=true;f.querySelector('.formerr').textContent='';try{await fn(Object.fromEntries(new FormData(f)),f)}catch(er){if(f.isConnected)f.querySelector('.formerr').textContent=er.message||'Не удалось сохранить.'}finally{button.disabled=false}}}

// ---- Экран входа: рабочий аккаунт или демо
function gate(tab='login'){
 st=null;document.body.classList.add('gate');document.body.classList.remove('offline');$('nav').innerHTML='';$('.mobileNav').innerHTML='';$('.sideFoot').innerHTML='<i></i> Рабочий режим';
 $('#crumb').textContent=tab==='register'?'Регистрация':'Вход';$('#heading').textContent='Kwast для малярных компаний';$('#sub').textContent='Размещайте объекты и предлагайте свои бригады. Одна компания может быть и заказчиком, и исполнителем.';
 const server=conn.server||defaultServer();
 const tabs='<div class="filter">'+act('gateTab','login','Вход','chip '+(tab==='login'?'active':''))+act('gateTab','register','Регистрация компании','chip '+(tab==='register'?'active':''))+'</div>';
 const srv=field('Адрес сервера',inp('server',server,'required inputmode="url" autocapitalize="off" autocorrect="off" spellcheck="false" placeholder="https://kwast.example.nl"'));
 const creds=field('E-mail',inp('email','','type="email" required autocomplete="username" autocapitalize="off"'))+field('Пароль',inp('password','','type="password" required minlength="8" autocomplete="'+(tab==='register'?'new-password':'current-password')+'"'));
 const body=tab==='register'?'<p class="note">Тестовая регистрация пилота. Используйте вымышленные реквизиты: настоящие документы и платежи в этой версии не обрабатываются.</p>'+field('Компания',inp('name','','required maxlength="65"'))+'<div class="cols">'+field('Город',opts())+field('Маляров в бригаде',inp('team',3,'type="number" min="1" max="200" required'))+'</div>'+field('Номер KvK (8 цифр, вымышленный)',inp('kvk','','inputmode="numeric" pattern="[0-9]{8}" maxlength="8" required'))+creds+srv:creds+srv;
 $('#view').innerHTML='<section class="panel gatePanel">'+tabs+'<form class="fields" id="entry">'+body+'<div class="formerr" role="alert"></div><button type="submit" class="primary">'+(tab==='register'?'Создать аккаунт':'Войти')+'</button></form><div class="gateDemo"><p class="muted">Нужно показать приложение без регистрации?</p>'+act('demo','','Открыть демо-режим')+'</div></section>';
 onSubmit(async d=>{
  const s=normServer(d.server);if(!s)throw Error('Укажите адрес сервера.');
  setConn({mode:'server',server:s});
  const r=await api('POST',tab==='register'?'/api/register':'/api/login',tab==='register'?{...d,team:+d.team,server:undefined}:{email:d.email,password:d.password});
  setConn({mode:'server',server:s,token:r.token});page='jobs';render();startPolling();toast(tab==='register'?'Компания зарегистрирована':'Вы вошли как '+me().name)
 })
}

function publish(){form('НОВЫЙ ОБЪЕКТ','Разместить объект',field('Название',inp('title','','required maxlength="85" placeholder="Например, покраска офиса"'))+field('Город',opts())+'<div class="cols">'+field('Начало',inp('start',day(1),'type="date" min="'+day(0)+'" required'))+field('Завершение',inp('end',day(5),'type="date" required'))+'</div><div class="cols">'+field('Площадь, м²',inp('area','','type="number" min="1" max="999999" required'))+field('Нужно маляров',inp('team',2,'type="number" min="1" max="200" required'))+'</div>'+field('Бюджет, €',inp('price','','type="number" min="1" max="10000000" step=".01" required'))+field('Описание работ','<textarea name="desc" required maxlength="1800"></textarea>'),'Опубликовать');onSubmit(async d=>{if(d.end<d.start)throw Error('Дата завершения должна быть не раньше начала.');if(!d.title.trim()||!d.desc.trim())throw Error('Введите название и описание.');
 if(remote){const r=await api('POST','/api/jobs',{title:d.title,city:d.city,start:d.start,end:d.end,area:+d.area,team:+d.team,price:+d.price,desc:d.desc});page='jobs';filter='all';render();showJob(r.id);toast('Объект опубликован');return}
 const j={...d,title:d.title.trim(),id:uid(),status:'open',owner:st.me,offers:[],accepted:null,team:+d.team,area:+d.area,price:+d.price};if(save(()=>st.jobs.unshift(j))){page='jobs';filter='all';render();showJob(j.id);toast('Объект опубликован в демо')}})}
function offer(id){const j=job(id);if(!j||j.owner===st.me||j.status!=='open')return;if(!available(j,st.me)){toast('Недостаточно свободных маляров на эти даты.');return}form('ОТКЛИК НА ОБЪЕКТ','Предложить бригаду','<p>'+esc(j.title)+' · '+date(j.start)+' – '+date(j.end)+' · '+j.team+' чел.</p>'+field('Ваша цена за работы, €',inp('amount',j.price,'type="number" min="1" max="10000000" step=".01" required'))+field('Условия предложения','<textarea name="note" maxlength="1000" required placeholder="Когда готовы начать?"></textarea>')+'<div id="total">'+settle(st.me,j.price)+'</div>','Отправить предложение');$('#entry [name=amount]').oninput=e=>$('#total').innerHTML=settle(st.me,Number(e.target.value));onSubmit(async d=>{if(!available(j,st.me))throw Error('Недостаточно свободных маляров на эти даты.');if(!d.note.trim())throw Error('Укажите условия предложения.');
 if(remote){await api('POST','/api/jobs/'+encodeURIComponent(id)+'/offers',{price:+d.amount,note:d.note});render();showJob(id);toast('Предложение отправлено');return}
 if(!j.offers.some(o=>o.by===st.me)&&save(()=>j.offers.push({by:st.me,price:+d.amount,note:d.note.trim()}))){render();showJob(id);toast('Предложение отправлено')}})}
function uid(){return 'u'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
async function shrink(f){if(!f?.size)return '';if(f.size>8000000)throw Error('Выберите изображение до 8 МБ.');const u=URL.createObjectURL(f);try{const im=new Image();im.src=u;await im.decode();const scale=Math.min(1,800/Math.max(im.width,im.height)),a=document.createElement('canvas');a.width=Math.max(1,Math.round(im.width*scale));a.height=Math.max(1,Math.round(im.height*scale));a.getContext('2d').drawImage(im,0,0,a.width,a.height);return a.toDataURL('image/jpeg',.68)}finally{URL.revokeObjectURL(u)}}
function profileForm(edit){const c=edit?me():{};form('ПРОФИЛЬ КОМПАНИИ',edit?'Изменить профиль':'Регистрация демо-компании','<p class="note">'+(remote?'Профиль хранится на сервере и виден другим компаниям.':'Тестовый профиль на этом устройстве.')+' Используйте вымышленные реквизиты и учебные документы.</p>'+field('Компания',inp('name',c.name,'required maxlength="65"'))+'<div class="cols">'+field('Город',opts(c.city))+field('Размер бригады',inp('team',c.team||2,'type="number" min="1" max="200" required'))+'</div>'+field('Номер KvK (8 цифр)',inp('kvk',c.kvk,'inputmode="numeric" pattern="[0-9]{8}" maxlength="8" '+(c.demo?'':'required')))+field('О команде / CV','<textarea name="cv" maxlength="1200">'+esc(c.cv)+'</textarea>')+field('Опыт — компания-заказчик',inp('experience',c.experience,'maxlength="100"'))+field('Фото профиля','<input name="portrait" type="file" accept="image/*">')+field('Добавить работы в портфолио (до 4 фото)','<input name="gallery" type="file" multiple accept="image/*">')+field('Учебная фактура для проверки опыта','<input name="proof" type="file" accept=".pdf,image/*">')+'<p class="note">Файл фактуры никуда не загружается и не читается: сохраняется только отметка «Ожидает проверки». Загрузка настоящих фактур — отдельный этап.</p>',edit?'Сохранить':'Создать профиль');onSubmit(async(d,f)=>{if(!d.name.trim())throw Error('Введите название компании.');const images=Array.from(f.elements.gallery.files);if(images.length+(c.gallery?.length||0)>4)throw Error('Можно добавить не больше четырёх фото портфолио.');if(d.proof.size&&!d.experience.trim())throw Error('Укажите, к какой компании относится фактура.');const gallery=[...(c.gallery||[]),...await Promise.all(images.map(shrink))],newPortrait=await shrink(d.portrait),portrait=newPortrait||c.portrait||'',proof=d.proof.size?'pending':c.experience===d.experience?c.proof:null;
 if(remote){await api('PUT','/api/me',{name:d.name,city:d.city,team:+d.team,kvk:d.kvk,cv:d.cv,experience:d.experience,gallery,portrait:newPortrait||undefined,proofRequested:!!d.proof.size});render();profile(st.me);toast('Профиль сохранён');return}
 if(edit&&st.jobs.some(j=>j.status==='booked'&&j.accepted===c.id&&!available(j,c.id,+d.team)))throw Error('Число маляров меньше уже забронированного на эти даты.');const row={...c,id:c.id||uid(),name:d.name.trim(),team:+d.team,city:d.city,cv:d.cv,kvk:d.kvk,experience:d.experience,gallery,portrait,proof};if(save(()=>{if(edit)Object.assign(c,row);else{st.companies.push(row);st.me=row.id}})){render();profile(row.id);toast('Профиль сохранён')}})}
function confirmAction(id,by,finish){const j=job(id),o=j?.offers.find(x=>x.by===(finish?j.accepted:by));if(!o||j.owner!==st.me||j.status!==(finish?'booked':'open'))return;if(!finish&&!available(j,by)){toast('На эти даты у бригады недостаточно свободных маляров.');return}modal('ПОДТВЕРЖДЕНИЕ','<h2>'+(finish?'Завершить работы?':'Забронировать бригаду?')+'</h2><p>'+esc(j.title)+' · '+esc(company(o.by).name)+'</p><div class="info">'+date(j.start)+' – '+date(j.end)+' · '+j.team+' чел.</div>'+settle(o.by,o.price)+(remote&&!finish?'<p class="note">Сервер ещё раз проверит, что у бригады хватает свободных маляров на эти даты.</p>':'')+'<div class="actions">'+act(finish?'doFinish':'doBook',j.id+'|'+o.by,finish?'Завершить':'Подтвердить бронь','primary')+act('job',j.id,'Назад')+'</div>')}
function decide(a,jid,by){const j=job(jid);if(j?.owner!==st.me||!j.offers.some(o=>o.by===by)||j.status!==(a==='doBook'?'open':'booked')||(a==='doFinish'&&j.accepted!==by))return;
 if(remote)return remoteAct(async()=>{await api('POST','/api/jobs/'+encodeURIComponent(jid)+(a==='doBook'?'/book':'/finish'),a==='doBook'?{crew:by}:undefined);render();showJob(jid);toast(a==='doBook'?'Бригада забронирована':'Работы завершены')},jid);
 if(a==='doBook'&&!available(j,by)){toast('Бригада уже занята в эти даты.');return}if(save(()=>{j.accepted=by;j.status=a==='doBook'?'booked':'done'})){render();showJob(jid);toast(a==='doBook'?'Бригада забронирована':'Работы завершены')}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-page],[data-action]');if(!el)return;e.preventDefault();if(el.dataset.page){if(!st)return;page=el.dataset.page;render();window.scrollTo(0,0);return}const {action:a,id}=el.dataset;
 if(a==='gateTab'){gate(id);return}if(a==='demo'){enterDemo();return}if(a==='login'){setConn({mode:'server',server:conn.server});st=null;dlg.close();gate('login');return}
 if(!st)return;
 if(a==='filter'){filter=id;render()}else if(a==='mode'){mode=id;render()}else if(a==='job')showJob(id);else if(a==='newJob')publish();else if(a==='offer')offer(id);else if(a==='profile')profile(id);else if(a==='editProfile'||a==='newProfile')profileForm(a==='editProfile');
 else if(a==='signOut')signOut();else if(a==='refresh'){remoteAct(async()=>{await refresh();dlg.close();render();toast('Данные обновлены')})}
 else if(a==='switch'&&!remote&&company(id)){if(save(()=>st.me=id)){dlg.close();render();toast('Кабинет: '+me().name)}}else if(a==='cancelBooking'||a==='doCancel')cancelBooking(job(id),a==='doCancel');else if(a==='book'||a==='finish'){const [jid,by]=id.split('|');confirmAction(jid,by,a==='finish')}else if(a==='doBook'||a==='doFinish'){const [jid,by]=id.split('|');decide(a,jid,by)}});
window.addEventListener('storage',e=>{if(remote||e.key!==key||!e.newValue)return;try{const next=JSON.parse(e.newValue);if(next.companies?.length&&Array.isArray(next.jobs)){st=next;if(dlg.open)dlg.close();render()}}catch{}});

// ---- Запуск
(async()=>{
 if(conn.mode==='demo'){loadDemo();render();return}
 if(remote&&conn.token){
  const cache=readJSON(cacheKey);if(cache?.server===conn.server&&cache.state){st={...cache.state,bookings:cache.state.bookings||[]};render()}
  try{await refresh();render();startPolling()}catch(e){if(e.status===0&&st){offline=true;render();startPolling();toast(e.message)}else if(e.status!==401){gate('login');toast(e.message)}}
  return
 }
 gate('login')
})();
